// Build-time prerender of the SEO pages (runs after `vite build`, from the
// `pulsemap-prerender` plugin in vite.config.ts).
//
// It starts from dist/index.html and writes dist/<path>/index.html for:
//   - /sortir-ce-soir/<ville> and /categories/... listed in dist/sitemap-tier*.xml
//   - /evenements/<slug> listed in dist/sitemap-events.xml (max 3500)
//   - /villes
// The URL lists come from the sitemaps (generated by scripts/generate-sitemap.ts,
// which applies the 5-event thresholds and isEventIndexable), so no rule is
// duplicated here. Titles, descriptions and JSON-LD come from
// src/lib/seo/pageMeta.ts and src/lib/seo/seoHead.ts, the same code the React
// pages use. React replaces #root on mount, exactly like the homepage fallback.
//
// This script never fails the build: on any error it logs and exits 0, and the
// SPA fallback keeps serving every page that was not written.

process.env.TZ = 'Europe/Paris';

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'fs';
import { resolve, join } from 'path';
import { CITY_SLUGS, CATEGORY_SLUGS, eventSlug, parseEventSlug, slugify } from '../src/lib/seo/slug';
import { computeSeoHead, type SeoInput } from '../src/lib/seo/seoHead';
import {
  buildCityMeta, buildCategoryMeta, buildEventMeta, CITIES_INDEX_META,
  type CityEventInput, type SeoIntroInput,
} from '../src/lib/seo/pageMeta';
import { SOURCE_ENTRIES, SOURCES_INTRO, SOURCES_DISCLAIMER, SOURCES_META, takedownText } from '../src/lib/seo/sourcesContent';

const MAX_EVENT_PAGES = 3500;
const DIST = resolve(process.argv[2] || 'dist');

interface Row extends CityEventInput { type: string }

// ---------- escaping ----------
const esc = (s: unknown) =>
  String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]!));
const ldJson = (o: unknown) =>
  JSON.stringify(o)
    .replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026')
    .replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');

// AI intros are generated by us, but keep only basic formatting tags anyway.
const ALLOWED = new Set(['p', 'strong', 'em', 'b', 'i', 'ul', 'ol', 'li', 'h2', 'h3', 'br']);
const safeIntro = (html: string) =>
  html
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<\/?([a-z0-9]+)[^>]*>/gi, (m, t) => {
      const tag = String(t).toLowerCase();
      return ALLOWED.has(tag) ? `<${m[1] === '/' ? '/' : ''}${tag}>` : '';
    });

// ---------- head ----------
function headTags(input: SeoInput): string {
  const h = computeSeoHead(input);
  const t: string[] = [
    `<title>${esc(h.title)}</title>`,
    `<meta name="description" content="${esc(h.description)}" />`,
    `<link rel="canonical" href="${esc(h.url)}" />`,
  ];
  if (h.noindex) t.push(`<meta name="robots" content="noindex,nofollow" />`);
  t.push(
    `<meta property="og:title" content="${esc(h.ogTitle)}" />`,
    `<meta property="og:description" content="${esc(h.ogDescription)}" />`,
    `<meta property="og:type" content="${esc(h.ogType)}" />`,
    `<meta property="og:url" content="${esc(h.url)}" />`,
    `<meta property="og:image" content="${esc(h.image)}" />`,
    `<meta property="og:image:secure_url" content="${esc(h.image)}" />`,
  );
  if (h.isDefaultImage) t.push(`<meta property="og:image:type" content="image/png" />`);
  if (h.imageWidth) t.push(`<meta property="og:image:width" content="${h.imageWidth}" />`);
  if (h.imageHeight) t.push(`<meta property="og:image:height" content="${h.imageHeight}" />`);
  if (h.imageAlt) t.push(`<meta property="og:image:alt" content="${esc(h.imageAlt)}" />`);
  t.push(
    `<meta property="og:site_name" content="PulseMap" />`,
    `<meta property="og:locale" content="fr_FR" />`,
    `<meta name="twitter:card" content="summary_large_image" />`,
    `<meta name="twitter:title" content="${esc(h.ogTitle)}" />`,
    `<meta name="twitter:description" content="${esc(h.ogDescription)}" />`,
    `<meta name="twitter:image" content="${esc(h.image)}" />`,
  );
  if (h.imageAlt) t.push(`<meta name="twitter:image:alt" content="${esc(h.imageAlt)}" />`);
  for (const x of h.hreflang) t.push(`<link rel="alternate" hreflang="${esc(x.lang)}" href="${esc(x.href)}" />`);
  for (const ld of h.jsonLd) t.push(`<script type="application/ld+json">${ldJson(ld)}</script>`);
  return t.map((x) => `    ${x}`).join('\n');
}

// ---------- body helpers ----------
const WRAP = 'max-width:720px;margin:0 auto;padding:32px 20px;font-family:system-ui,-apple-system,sans-serif;color:#e6e6f0;line-height:1.5';
const A = 'style="color:#f2a7d4;text-decoration:none"';
const H2 = 'style="font-size:18px;margin:24px 0 8px"';
const MUTED = 'style="margin:0 0 16px;color:#b8b8cc"';
const link = (href: string, text: string) => `<a href="${esc(href)}" ${A}>${esc(text)}</a>`;
const inlineList = (items: string[]) =>
  `<ul style="list-style:none;padding:0;margin:0 0 8px">${items.map((i) => `<li style="display:inline-block;margin:0 12px 8px 0">${i}</li>`).join('')}</ul>`;
const shortDate = (iso: string) =>
  new Date(iso).toLocaleString('fr-FR', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Paris' });
const crumbs = (items: [string, string | null][]) =>
  `<nav aria-label="Fil d'ariane" style="font-size:14px;margin:0 0 16px;color:#b8b8cc">${items
    .map(([t, h]) => (h ? link(h, t) : `<span>${esc(t)}</span>`)).join(' / ')}</nav>`;
const eventList = (evs: { id: string; name: string; venue: string; start_time: string }[]) =>
  `<ul style="padding-left:18px;margin:0 0 8px">${evs
    .map((e) => `<li style="margin:0 0 6px">${link(`/evenements/${eventSlug(e.name, e.id)}`, e.name)} <span style="color:#b8b8cc">${esc(shortDate(e.start_time))}${e.venue ? `, ${esc(e.venue)}` : ''}</span></li>`)
    .join('')}</ul>`;
const faqHtml = (faqs: { q: string; a: string }[]) =>
  `<h2 ${H2}>Questions fréquentes</h2>${faqs.map((f) => `<h3 style="font-size:15px;margin:12px 0 4px">${esc(f.q)}</h3><p ${MUTED}>${esc(f.a)}</p>`).join('')}`;
const page = (inner: string) => `<main style="${WRAP}">${inner}</main>`;

function render(template: string, head: string, body: string): string {
  let html = template
    .replace(/<title>[\s\S]*?<\/title>\s*/i, '')
    .replace(/<meta\s+(?:name|property)="(?:description|og:[^"]*|twitter:[^"]*)"[^>]*>\s*/gi, '')
    .replace(/<link\s+rel="canonical"[^>]*>\s*/gi, '')
    .replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>\s*/gi, '');
  html = html.replace('</head>', `${head}\n  </head>`);
  const start = html.indexOf('<div id="root">');
  const nsEnd = html.indexOf('</noscript>', start);
  if (start === -1 || nsEnd === -1) throw new Error('root/noscript markers not found in dist/index.html');
  return html.slice(0, start) + `<div id="root">${body}</div>` + html.slice(nsEnd + '</noscript>'.length);
}

// ---------- data ----------
async function rest<T>(path: string, range?: [number, number]): Promise<T[]> {
  const url = process.env.VITE_SUPABASE_URL;
  const key = process.env.VITE_SUPABASE_PUBLISHABLE_KEY;
  if (!url || !key) throw new Error('missing backend env');
  const headers: Record<string, string> = { apikey: key, Authorization: `Bearer ${key}` };
  if (range) headers.Range = `${range[0]}-${range[1]}`;
  const r = await fetch(`${url}/rest/v1/${path}`, { headers, signal: AbortSignal.timeout(30000) });
  if (!r.ok) throw new Error(`${path} -> ${r.status}`);
  return (await r.json()) as T[];
}

async function fetchRows(): Promise<Row[]> {
  const nowIso = new Date().toISOString();
  const cols = 'id,name,city,venue,address,lat,lng,start_time,end_time,description,image_url,ticket_url,price_range,type';
  const rows: Row[] = [];
  for (let from = 0; from < 60000; from += 1000) {
    const batch = await rest<Row>(
      `cached_events?select=${cols}&or=(start_time.gte.${nowIso},end_time.gte.${nowIso})&order=start_time.asc,id.asc`,
      [from, from + 999],
    );
    rows.push(...batch);
    if (batch.length < 1000) break;
  }
  return rows;
}

function sitemapPaths(file: string): string[] {
  const p = join(DIST, file);
  if (!existsSync(p)) return [];
  return [...readFileSync(p, 'utf8').matchAll(/<loc>([^<]+)<\/loc>/g)]
    .map((m) => m[1].replace(/&amp;/g, '&').replace(/^https?:\/\/[^/]+/, ''));
}

const SAFE_PATH = /^\/[A-Za-z0-9_\-/]+$/;
function writePage(path: string, html: string): boolean {
  if (!SAFE_PATH.test(path) || path.includes('..')) return false;
  const dir = join(DIST, path);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, 'index.html'), html);
  return true;
}

// ---------- main ----------
async function main() {
  const t0 = Date.now();
  const tplPath = join(DIST, 'index.html');
  if (!existsSync(tplPath)) { console.warn('[prerender] dist/index.html missing, skipped'); return; }
  const template = readFileSync(tplPath, 'utf8');
  const counts = { villes: 0, sources: 0, city: 0, category: 0, event: 0, skipped: 0 };

  // /villes : static content, no data needed.
  const cityEntries = Object.entries(CITY_SLUGS);
  const catEntries = Object.entries(CATEGORY_SLUGS);
  {
    const head = headTags({
      title: CITIES_INDEX_META.title, description: CITIES_INDEX_META.description,
      canonical: CITIES_INDEX_META.canonical, jsonLd: CITIES_INDEX_META.jsonLd(),
    });
    const body = page(
      crumbs([['Accueil', '/'], ['Villes', null]]) +
      `<h1 style="font-size:26px;margin:0 0 12px">${esc(CITIES_INDEX_META.h1)}</h1><p ${MUTED}>${esc(CITIES_INDEX_META.intro)}</p>` +
      `<h2 ${H2}>Sortir ce soir, par ville</h2>` + inlineList(cityEntries.map(([s, n]) => link(`/sortir-ce-soir/${s}`, `Sortir ce soir à ${n}`))) +
      `<h2 ${H2}>Catégories</h2>` + inlineList(catEntries.map(([s, c]) => link(`/categories/${s}`, c.label))),
    );
    if (writePage('/villes', render(template, head, body))) counts.villes++;
  }

  // /sources : contenu statique partage avec SourcesPage.tsx.
  {
    const head = headTags({ title: SOURCES_META.title, description: SOURCES_META.description, canonical: SOURCES_META.canonical });
    const body = page(
      crumbs([['Accueil', '/'], [SOURCES_META.h1, null]]) +
      `<h1 style="font-size:26px;margin:0 0 12px">${esc(SOURCES_META.h1)}</h1><p ${MUTED}>${esc(SOURCES_INTRO)}</p>` +
      SOURCE_ENTRIES.map((s) =>
        `<h2 ${H2}>${esc(s.name)}</h2><p ${MUTED}>${esc(s.role)} ${esc(s.shown)} ${esc(s.license)}</p>`).join('') +
      `<h2 ${H2}>Exactitude des informations</h2><p ${MUTED}>${esc(SOURCES_DISCLAIMER)}</p>` +
      `<h2 ${H2} id="retrait">Retrait d'un contenu</h2><p ${MUTED}>${esc(takedownText())}</p>`,
    );
    if (writePage('/sources', render(template, head, body))) counts.sources++;
  }

  let rows: Row[] = [];
  let intros = new Map<string, SeoIntroInput>();
  try {
    rows = await fetchRows();
    const ir = await rest<SeoIntroInput & { city_slug: string }>('city_seo_intros?select=city_slug,h1,intro_html,meta_description');
    intros = new Map(ir.map((r) => [r.city_slug, r]));
  } catch (e) {
    console.warn('[prerender] data unavailable, only /villes prerendered:', e instanceof Error ? e.message : e);
    return report(counts, t0);
  }

  const tierPaths = ['sitemap-tier1.xml', 'sitemap-tier2.xml', 'sitemap-tier3.xml'].flatMap(sitemapPaths);
  const cityPaths = tierPaths.filter((p) => /^\/sortir-ce-soir\/[^/]+$/.test(p));
  const catPaths = tierPaths.filter((p) => /^\/categories\/[^/]+(\/[^/]+)?$/.test(p));
  const prerenderedCities = new Set(cityPaths.map((p) => p.split('/')[2]));
  const prerenderedCats = new Set(catPaths);

  const byCity = new Map<string, Row[]>();
  for (const r of rows) {
    const k = (r.city || '').toLowerCase();
    if (!byCity.has(k)) byCity.set(k, []);
    byCity.get(k)!.push(r);
  }
  const eventsOf = (cityName: string) => byCity.get(cityName.toLowerCase()) || [];
  const citySlugOf = (city: string) => {
    const s = slugify(city);
    return CITY_SLUGS[s] ? s : null;
  };

  // City centroids for "villes voisines".
  const centroid = new Map<string, [number, number]>();
  for (const slug of prerenderedCities) {
    const ev = eventsOf(CITY_SLUGS[slug] || '').filter((e) => Number.isFinite(e.lat) && Number.isFinite(e.lng));
    if (ev.length) centroid.set(slug, [ev.reduce((a, e) => a + e.lat, 0) / ev.length, ev.reduce((a, e) => a + e.lng, 0) / ev.length]);
  }
  const nearby = (slug: string) => {
    const c = centroid.get(slug);
    if (!c) return [] as string[];
    return [...centroid.entries()].filter(([s]) => s !== slug)
      .map(([s, [la, ln]]) => [s, (la - c[0]) ** 2 + ((ln - c[1]) * Math.cos((c[0] * Math.PI) / 180)) ** 2] as const)
      .sort((a, b) => a[1] - b[1]).slice(0, 6).map(([s]) => s);
  };

  // /sortir-ce-soir/<ville>
  for (const path of cityPaths) {
    try {
      const slug = path.split('/')[2];
      const cityName = CITY_SLUGS[slug];
      if (!cityName) { counts.skipped++; continue; }
      const events = eventsOf(cityName).slice(0, 60);
      const aiIntro = intros.get(slug) || null;
      const m = buildCityMeta({ slug, cityName, events, aiIntro, isSortirRoute: true });
      const head = headTags({ title: m.title, description: m.description, ogTitle: m.ogTitle, ogDescription: m.ogDescription, canonical: m.canonical, jsonLd: m.ld, hreflang: m.hreflang });
      const cats = catEntries.filter(([s]) => prerenderedCats.has(`/categories/${s}/${slug}`));
      const body = page(
        crumbs([['Accueil', '/'], ['Villes', '/villes'], [cityName, null]]) +
        `<h1 style="font-size:26px;margin:0 0 12px">${esc(aiIntro?.h1 || `Sortir ce soir à ${cityName}`)}</h1>` +
        (aiIntro?.intro_html ? `<div style="color:#b8b8cc">${safeIntro(aiIntro.intro_html)}</div>` : `<p ${MUTED}>${esc(m.description)}</p>`) +
        `<p>${link('/', `Voir la carte des sorties à ${cityName}`)}</p>` +
        (events.length ? `<h2 ${H2}>Prochains événements à ${esc(cityName)}</h2>` + eventList(events.slice(0, 30)) : '') +
        (m.topVenues.length ? `<h2 ${H2}>Lieux programmés à ${esc(cityName)}</h2><p ${MUTED}>${esc(m.topVenues.join(' · '))}</p>` : '') +
        (cats.length ? `<h2 ${H2}>Par catégorie à ${esc(cityName)}</h2>` + inlineList(cats.map(([s, c]) => link(`/categories/${s}/${slug}`, `${c.label} à ${cityName}`))) : '') +
        (nearby(slug).length ? `<h2 ${H2}>Villes proches</h2>` + inlineList(nearby(slug).map((s) => link(`/sortir-ce-soir/${s}`, `Sortir à ${CITY_SLUGS[s]}`))) : '') +
        faqHtml(m.faqs) +
        `<p style="margin-top:24px">${link('/villes', 'Toutes les villes')}</p>`,
      );
      if (writePage(path, render(template, head, body))) counts.city++; else counts.skipped++;
    } catch (e) { counts.skipped++; console.warn('[prerender] city failed', path, e); }
  }

  // /categories/<cat> and /categories/<cat>/<ville>
  for (const path of catPaths) {
    try {
      const [, , catSlug, citySlug] = path.split('/');
      const cat = CATEGORY_SLUGS[catSlug];
      const cityName = citySlug ? CITY_SLUGS[citySlug] : undefined;
      if (!cat || (citySlug && !cityName)) { counts.skipped++; continue; }
      const pool = cityName ? eventsOf(cityName) : rows;
      const events = pool.filter((e) => cat.types.includes(e.type)).slice(0, 80);
      const aiIntro = citySlug && catSlug === 'soirees' ? intros.get(citySlug) || null : null;
      const m = buildCategoryMeta({ slug: catSlug, cat, citySlug, cityName, events, aiIntro, loading: false });
      const head = headTags({ title: m.title, description: m.description, canonical: m.canonical, noindex: m.emptyCityPage, jsonLd: m.jsonLd });
      const otherCats = catEntries.filter(([s]) => s !== catSlug)
        .map(([s, c]) => (cityName && prerenderedCats.has(`/categories/${s}/${citySlug}`) ? link(`/categories/${s}/${citySlug}`, `${c.label} à ${cityName}`) : link(`/categories/${s}`, c.label)));
      const citiesWithCat = cityEntries.filter(([s]) => s !== citySlug && prerenderedCats.has(`/categories/${catSlug}/${s}`));
      const body = page(
        crumbs(cityName ? [['Accueil', '/'], ['Villes', '/villes'], [cityName, `/sortir-ce-soir/${citySlug}`], [cat.label, null]] : [['Accueil', '/'], ['Villes', '/villes'], [cat.label, null]]) +
        `<h1 style="font-size:26px;margin:0 0 12px">${esc(m.h1)}</h1>` +
        (aiIntro?.intro_html ? `<div style="color:#b8b8cc">${safeIntro(aiIntro.intro_html)}</div>` : `<p ${MUTED}>${esc(cat.description)}</p>`) +
        (events.length ? `<h2 ${H2}>Prochains ${esc(m.labelLower)}${cityName ? ` à ${esc(cityName)}` : ''}</h2>` + eventList(events.slice(0, 30)) : '') +
        (cityName ? `<p>${link(`/sortir-ce-soir/${citySlug}`, `Toutes les sorties à ${cityName}`)}</p>` : '') +
        `<h2 ${H2}>Autres catégories</h2>` + inlineList(otherCats) +
        (citiesWithCat.length ? `<h2 ${H2}>${esc(cat.label)} dans d'autres villes</h2>` + inlineList(citiesWithCat.map(([s, n]) => link(`/categories/${catSlug}/${s}`, `${cat.label} à ${n}`))) : '') +
        faqHtml(m.faqs),
      );
      if (writePage(path, render(template, head, body))) counts.category++; else counts.skipped++;
    } catch (e) { counts.skipped++; console.warn('[prerender] category failed', path, e); }
  }

  // /evenements/<slug>
  const byId = new Map(rows.map((r) => [r.id, r]));
  const eventPaths = sitemapPaths('sitemap-events.xml').filter((p) => p.startsWith('/evenements/')).slice(0, MAX_EVENT_PAGES);
  for (const path of eventPaths) {
    try {
      const slug = path.slice('/evenements/'.length);
      const event = byId.get(parseEventSlug(slug));
      if (!event) { counts.skipped++; continue; }
      const m = buildEventMeta({ slug, event, engagement: { favorites: 0, attendances: 0 } });
      const head = headTags({ title: m.title, description: m.description, canonical: m.canonical, image: event.image_url || undefined, type: 'event', jsonLd: m.ld });
      const citySlug = citySlugOf(event.city);
      const cityHref = citySlug ? `/sortir-ce-soir/${citySlug}` : `/sortir-ce-soir/${m.cityLower}`;
      const mapsHref = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([event.venue, event.address].filter(Boolean).join(', '))}`;
      const sameVenue = rows.filter((r) => r.venue && r.venue === event.venue && r.id !== event.id).slice(0, 6);
      const body = page(
        crumbs([['Accueil', '/'], ['Villes', '/villes'], [event.name, null]]) +
        `<h1 style="font-size:26px;margin:0 0 8px">${esc(event.name)}</h1>` +
        `<p ${MUTED}>${esc(m.dateLabel)} · ${esc(m.timeLabel)} · ${esc(event.venue)}, ${esc(event.city)}</p>` +
        (event.address ? `<p style="margin:0 0 16px">Adresse : ${link(mapsHref, event.address)}</p>` : '') +
        (event.description ? `<p style="margin:0 0 16px">${esc(event.description).replace(/\n+/g, '<br />')}</p>` : '') +
        (event.ticket_url ? `<p>${`<a href="${esc(event.ticket_url)}" rel="nofollow noopener" ${A}>Billetterie et infos</a>`}</p>` : '') +
        `<p>${link(mapsHref, `Voir ${event.venue || 'le lieu'} sur la carte`)}</p>` +
        (sameVenue.length ? `<h2 ${H2}>Au même endroit</h2>` + eventList(sameVenue) : '') +
        `<p style="margin-top:24px">Plus de sorties à ${link(cityHref, event.city)}</p>`,
      );
      if (writePage(path, render(template, head, body))) counts.event++; else counts.skipped++;
    } catch (e) { counts.skipped++; console.warn('[prerender] event failed', path, e); }
  }

  report(counts, t0);
}

function report(c: Record<string, number>, t0: number) {
  console.log(`[prerender] villes:${c.villes} sortir-ce-soir:${c.city} categories:${c.category} evenements:${c.event} ignorees:${c.skipped} en ${((Date.now() - t0) / 1000).toFixed(1)}s`);
}

main()
  .catch((e) => console.warn('[prerender] failed, SPA fallback kept:', e))
  .finally(() => process.exit(0));
